import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { extractPage } from '../extract/html.js';
import { HostRateLimiter, safeFetch, type FetchOptions } from '../net/fetcher.js';
import type { KnowledgeBase } from './engine.js';

/**
 * Official-source revalidation. Fetches every source URL of the knowledge base and compares it with the
 * previous snapshot: HTTP status, final URL (redirects), page title, the page's own "last updated" date
 * and a hash of its main text. Changes do not edit rules; they tell a maintainer which rules to re-read.
 */
export interface SourceSnapshot {
  url: string;
  fetchedAt: string;
  status: number;
  finalUrl: string;
  title: string | null;
  /** Date the page itself declares (Google/web.dev "Last updated", MDN "last modified"). */
  lastUpdated: string | null;
  /** SHA-256 of the normalised main text; null when the page could not be read. */
  contentHash: string | null;
  /** Main text shorter than this usually means a client-rendered page (content not in the HTML). */
  textLength: number;
  error?: string;
}

export type SourceChange = 'new' | 'unchanged' | 'content-changed' | 'date-changed' | 'redirected' | 'broken' | 'unreadable';

export interface SourceCheckResult {
  url: string;
  change: SourceChange;
  rules: string[];
  previous?: SourceSnapshot;
  current: SourceSnapshot;
  detail: string;
}

export function snapshotFile(knowledgeDir: string): string {
  return path.join(knowledgeDir, 'source-snapshots.json');
}

export function readSnapshots(file: string): Record<string, SourceSnapshot> {
  if (!fs.existsSync(file)) return {};
  return (JSON.parse(fs.readFileSync(file, 'utf8')) as { sources: Record<string, SourceSnapshot> }).sources ?? {};
}

export function writeSnapshots(file: string, sources: Record<string, SourceSnapshot>): void {
  const sorted = Object.fromEntries(Object.entries(sources).sort(([a], [b]) => a.localeCompare(b)));
  fs.writeFileSync(file, JSON.stringify({ note: 'Generated by `searvex rules check-sources --update`. Do not edit by hand.', sources: sorted }, null, 2) + '\n');
}

const MONTHS: Record<string, string> = { jan: '01', feb: '02', mar: '03', apr: '04', may: '05', jun: '06', jul: '07', aug: '08', sep: '09', oct: '10', nov: '11', dec: '12' };

/** Extract the page's own update date from known documentation-site patterns. */
export function extractLastUpdated(html: string): string | null {
  const google = /Last updated (\d{4}-\d{2}-\d{2}) UTC/.exec(html);
  if (google) return google[1]!;
  const mdn = /last modified on <time datetime="(\d{4}-\d{2}-\d{2})/i.exec(html);
  if (mdn) return mdn[1]!;
  const long = /Last (?:updated|modified)[:\s]+(?:on\s+)?([A-Z][a-z]{2})[a-z]*\.?\s+(\d{1,2}),\s+(\d{4})/.exec(html);
  if (long && MONTHS[long[1]!.toLowerCase()]) return `${long[3]}-${MONTHS[long[1]!.toLowerCase()]}-${long[2]!.padStart(2, '0')}`;
  const meta = /<meta[^>]+(?:property|name)=["'](?:article:modified_time|last-modified|dcterms\.modified)["'][^>]+content=["'](\d{4}-\d{2}-\d{2})/i.exec(html);
  return meta ? meta[1]! : null;
}

/** Normalise main text so that volatile fragments (dates, counters) do not change the hash. */
export function normaliseForHash(text: string): string {
  return text
    .replace(/Last (updated|modified)[^.]{0,60}/gi, '')
    .replace(/\d{4}-\d{2}-\d{2}(T[\d:.]+Z?)?/g, '')
    .replace(/\b\d+\s+(views?|comments?|likes?)\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

export async function fetchSourceSnapshot(url: string, opts: FetchOptions = {}): Promise<SourceSnapshot> {
  const res = await safeFetch(url, { timeoutMs: 20000, maxBytes: 4 * 1024 * 1024, ...opts });
  const base: SourceSnapshot = { url, fetchedAt: new Date().toISOString(), status: res.status, finalUrl: res.finalUrl, title: null, lastUpdated: null, contentHash: null, textLength: 0 };
  if (res.error) return { ...base, error: res.error };
  if (res.status >= 400 || !/html|xml|text/i.test(res.contentType)) return base;
  const page = extractPage(res.body, res.finalUrl);
  const text = normaliseForHash(page.mainText);
  return {
    ...base,
    title: page.title,
    lastUpdated: extractLastUpdated(res.body),
    contentHash: text.length >= 200 ? crypto.createHash('sha256').update(text).digest('hex') : null,
    textLength: text.length,
  };
}

const stripHash = (u: string) => u.replace(/#.*$/, '');
const sameUrl = (a: string, b: string) => stripHash(a).replace(/\/$/, '') === stripHash(b).replace(/\/$/, '');

export function compareSnapshot(prev: SourceSnapshot | undefined, cur: SourceSnapshot): { change: SourceChange; detail: string } {
  if (cur.error || cur.status >= 400 || cur.status === 0) return { change: 'broken', detail: cur.error ?? `HTTP ${cur.status}` };
  // A source that redirects should be updated in the knowledge base, whether or not it redirected before.
  if (!sameUrl(cur.finalUrl, cur.url)) return { change: 'redirected', detail: `redirects to ${cur.finalUrl} — update the rule's source URL` };
  if (!cur.contentHash) return { change: 'unreadable', detail: `main text too short (${cur.textLength} chars) — likely client-rendered; verify manually` };
  if (!prev || !prev.contentHash) return { change: 'new', detail: `baseline recorded${cur.lastUpdated ? ` (page updated ${cur.lastUpdated})` : ''}` };
  if (prev.lastUpdated && cur.lastUpdated && prev.lastUpdated !== cur.lastUpdated) return { change: 'date-changed', detail: `page updated ${prev.lastUpdated} → ${cur.lastUpdated}` };
  if (prev.contentHash !== cur.contentHash) return { change: 'content-changed', detail: 'main text changed since the last snapshot' };
  return { change: 'unchanged', detail: cur.lastUpdated ? `last updated ${cur.lastUpdated}` : 'content unchanged' };
}

export async function checkSources(
  kb: KnowledgeBase,
  previous: Record<string, SourceSnapshot>,
  opts: FetchOptions & { delayMs?: number; concurrency?: number; onProgress?: (done: number, total: number, url: string) => void } = {},
): Promise<SourceCheckResult[]> {
  const byUrl = new Map<string, string[]>();
  for (const r of kb.rules.values()) for (const s of r.sources) {
    const key = stripHash(s.url);
    byUrl.set(key, [...(byUrl.get(key) ?? []), r.id]);
  }
  const urls = [...byUrl.keys()].sort();
  const limiter = new HostRateLimiter(opts.delayMs ?? 1000);
  const results: SourceCheckResult[] = [];
  let done = 0;
  const queue = [...urls];
  const worker = async () => {
    for (let url = queue.shift(); url; url = queue.shift()) {
      await limiter.wait(new URL(url).host);
      const current = await fetchSourceSnapshot(url, opts);
      const prev = previous[url];
      const { change, detail } = compareSnapshot(prev, current);
      results.push({ url, change, rules: [...new Set(byUrl.get(url))].sort(), previous: prev, current, detail });
      opts.onProgress?.(++done, urls.length, url);
    }
  };
  await Promise.all(Array.from({ length: opts.concurrency ?? 4 }, worker));
  return results.sort((a, b) => a.url.localeCompare(b.url));
}
